-- PNC Business Line of Credit x2775, statements Feb–Oct 2026 (closing 02/05 … 10/08),
-- imported through lib/loanStatement.js (parseLoanText → planLoanStatement), the code
-- System → Line of Credit runs. Each statement balanced to the cent before posting.
--   interest / fees   Dr 7150 Interest Expense / 6850 Service Charge   Cr 2600 Line of Credit
--   payments          Dr 2600   Cr 1020 Checking   (each its own entry, on its own date)
--   draws             Dr 1020   Cr 2600            (the 01/09 draw links to JE-0019, already on the books)
-- Also sets up the line in settings.accounts.loans.
do $$ begin
  if (select next_value from org_sequences where org_id = '7a8cc248-e095-41d7-aebf-86ccc260733e' and doc_type = 'journal') <> 34 then raise exception 'journal numbering moved — regenerate this fix'; end if;
  if exists (select 1 from loan_statements) then raise exception 'loan statements already posted'; end if;
end $$;
update settings set data = jsonb_set(data, '{accounts,loans}', '[{"id":"7ef4d40f-9653-475e-a63b-68cb4c6d9bff","name":"PNC Line of Credit","account":"2600","cashAccount":"1020","interestAccount":"7150","feeAccount":"6850","match": "2775"}]'::jsonb) where org_id = '7a8cc248-e095-41d7-aebf-86ccc260733e';
update org_sequences set next_value = 55 where org_id = '7a8cc248-e095-41d7-aebf-86ccc260733e' and doc_type = 'journal';
